#!/usr/bin/env bash
set -euo pipefail
cd /home/drako/workspace/drako_base
pnpm exec wrangler d1 execute saas_socialflows_prod_db --remote --config=workers/socialflows/wrangler.workers.toml --command "SELECT tenant_id, saas_id, provider, status, display_name, handle, json_extract(auth_meta, '$.scope') AS oauth_scope, json_extract(auth_meta, '$.tokenType') AS token_type, json_extract(auth_meta, '$.profileId') AS profile_id, json_extract(auth_meta, '$.authorUrn') AS author_urn, json_extract(auth_meta, '$.lastValidationAt') AS last_validation_at, json_extract(auth_meta, '$.lastErrorCode') AS last_error_code, json_extract(auth_meta, '$.lastErrorMessage') AS last_error_message, CASE WHEN json_extract(auth_meta, '$.accessToken') LIKE 'encrypted:v1:aes-gcm:%' THEN 1 ELSE 0 END AS access_token_encrypted, CASE WHEN json_extract(auth_meta, '$.idToken') LIKE 'encrypted:v1:aes-gcm:%' THEN 1 ELSE 0 END AS id_token_encrypted, created_at, updated_at FROM saas_social_accounts WHERE tenant_id = 'tenant_socialflow_canary_staff' AND saas_id = 'p2-24i-saas' AND provider = 'LINKEDIN' LIMIT 1;" --json
